$q=$pdo->prepare("SELECT t.*,b.name account_name,b.opening_balance,\n       p.reference_no payment_ref,p.id payment_id,\n       g.invoice_no general_inv_no,\n       s.awb ship_awb,(SELECT si.invoice_no FROM shipment_invoices si WHERE si.shipment_id=p.shipment_id ORDER BY si.id DESC LIMIT 1) ship_inv_no,\n       ie.payer income_payer,ie.description income_desc,\n       ex.description expense_desc\nFROM bank_transactions t\nJOIN bank_accounts b ON b.id=t.bank_account_id\nLEFT JOIN payments p ON p.id=IF(t.source_table='payments',t.source_id,NULL)\nLEFT JOIN general_invoices g ON g.id=p.general_invoice_id\nLEFT JOIN shipments s ON s.id=p.shipment_id\nLEFT JOIN income_entries ie ON ie.id=IF(t.source_table='income_entries',t.source_id,NULL)\nLEFT JOIN expenses ex ON ex.id=IF(t.source_table='expenses',t.source_id,NULL)".$where.' ORDER BY t.bank_account_id,t.transaction_date,t.id');$q->execute($params);$rows=$q->fetchAll();
$balances=[];$data=[];foreach($rows as $r){$id=(int)$r['bank_account_id'];if(!isset($balances[$id]))$balances[$id]=(float)$r['opening_balance'];$balances[$id]+=(float)$r['amount_in']-(float)$r['amount_out'];if($from===''||$r['transaction_date']>=$from.' 00:00:00'){$type=(string)$r['transaction_type'];if($type==='Payment')$ref=$r['ship_inv_no']?:$r['general_inv_no']?:($r['ship_awb']?'AWB '.$r['ship_awb']:('Payment #'.$r['source_id']));elseif($type==='Income')$ref=$r['income_payer']?:$r['income_desc']?:('Income #'.$r['source_id']);else$ref=$r['expense_desc']?:('Expense #'.$r['source_id']);$data[]=[date('d M Y',strtotime($r['transaction_date'])),substr($r['account_name'],0,17),$type,substr($ref,0,15),number_format((float)$r['amount_in'],2),number_format((float)$r['amount_out'],2),number_format($balances[$id],2)];}}
