    $headers=['Date','Account','Transaction','Reference','Money In','Money Out','Balance'];$xs=[42,100,205,272,342,417,492];$widths=[58,105,67,70,75,75,78];$stream.="q\n0.10 0.35 0.54 rg 42 652 528 24 re f\nQ\n";foreach($headers as $i=>$_)pdf_label($stream,$xs[$i]+4,661,$headers[$i],'7','F2','1 1 1');$y=631;
    foreach($pageRows as $rowIndex=>$row){if(!$data){pdf_label($stream,185,$y,'No bank transactions found for this date range.','10','F1','0.35 0.42 0.48');break;}if($rowIndex%2===0)$stream.="q\n0.95 0.97 0.99 rg 42 ".($y-8)." 528 21 re f\nQ\n";$stream.="q\n0.86 0.89 0.92 RG 0.4 w 42 ".($y-8)." m 570 ".($y-8)." l S\nQ\n";foreach($row as $i=>$cell){$color=$i===4?'0.05 0.50 0.27':($i===5?'0.76 0.20 0.20':($i===6?'0.08 0.28 0.52':'0.10 0.16 0.24'));pdf_label($stream,$xs[$i]+4,$y,substr($cell,0,$i===1?17:($i===3?15:12)),'7',$i===6?'F2':'F1',$color);}$y-=21;}
